/**
 * Kern-Datenmodell von PulseBoard.
 *
 * Alles ist bewusst klein gehalten: Aktivitäten und ihr Tagesfortschritt.
 * Die Versionierung der gespeicherten Daten lebt in `StoredState.schemaVersion`.
 */

/** Einmal pro Aktivität. Name ist Pflicht, alles andere optional. */
export interface Activity {
  /** Stabil UUID-artifizielle ID (nicht veränderbar durch den Nutzer). */
  id: string;
  /** Pflichtfeld. */
  name: string;
  /** Optional, frei text. */
  description: string;
  /** Kategorie zum Gruppieren / Filtern im Dashboard. */
  category: string;
  /**
   * Tagesziel als Zahl. 0 (oder kleiner) bedeutet "kein Ziel".
   * Der Fortschritt pro Tag kann diesen Wert überschreiten.
   */
  dailyGoal: number;
  /** Optionaler ISO-Erstelldatum, rein informativ. */
  createdAt: string;
}

/**
 * Fortschritt eines Tages: { activityId : erledigteAnzahl }.
 * 0 = nicht erledigt, >=1 = erledigt (n-fach bei Tagesziel > 1).
 */
export type DayProgress = Record<string, number>;

/** Vollständiger, versionierter Zustand, wie er persistiert wird. */
export interface StoredState {
  schemaVersion: number;
  activities: Activity[];
  /** { date(YYYY-MM-DD) : DayProgress } */
  days: Record<string, DayProgress>;
  updatedAt: string;
}

export const SCHEMA_VERSION = 1;

/** Leerer Ausgangszustand. */
export function emptyState(): StoredState {
  return {
    schemaVersion: SCHEMA_VERSION,
    activities: [],
    days: {},
    updatedAt: new Date().toISOString(),
  };
}

/**
 * Kleines Datumshilfsmodul. Alle Datumsangaben werden intern als
 * 'YYYY-MM-DD' im LOKALEN Zeitformat gespeichert, damit ein Tag auf allen
 * Geräten konsistent ist und sich verschiedene Tage nicht überschreiben.
 */

/** Gibt das heutige Datum als 'YYYY-MM-DD' im lokalen Zeitformat zurück. */
export function todayLocal(): string {
  return formatDate(new Date());
}

/** Formatiert ein Datum als 'YYYY-MM-DD' im lokalen Zeitformat. */
export function formatDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

/** Addiert (oder subtriert) ganztägige Schritte zu einem 'YYYY-MM-DD'-String. */
export function addDays(date: string, steps: number): string {
  const d = parseLocal(date);
  if (!d) return date;
  d.setDate(d.getDate() + steps);
  return formatDate(d);
}

/** Liest einen 'YYYY-MM-DD'-String in ein lokales Datum. Ungültig => null. */
export function parseLocal(date: string): Date | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;
  const [y, m, d] = date.split('-').map(Number);
  const dt = new Date(y, m - 1, d);
  // Verhindert stille Roll-over (z. B. 2021-02-31 -> März).
  if (
    dt.getFullYear() !== y ||
    dt.getMonth() !== m - 1 ||
    dt.getDate() !== d
  ) {
    return null;
  }
  return dt;
}

/** Menschliches Format für die Tagesnavigation, z. B. "Donnerstag, 24. Sep.". */
export function formatDayLabel(date: string): string {
  const d = parseLocal(date);
  if (!d) return date;
  return new Intl.DateTimeFormat('de-DE', {
    weekday: 'long',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  }).format(d);
}

/** "Heute"/"Gestern"/"Morgen" oder Datum, je nach Nähe zum heutigen Tag. */
export function formatDayShort(date: string): string {
  const d = parseLocal(date);
  if (!d) return date;
  const today = parseLocal(todayLocal());
  if (!today) return date;
  const diff = Math.round(
    (d.getTime() - today.getTime()) / (1000 * 60 * 60 * 24),
  );
  if (diff === 0) return 'Heute';
  if (diff === -1) return 'Gestern';
  if (diff === 1) return 'Morgen';
  return new Intl.DateTimeFormat('de-DE', {
    day: '2-digit',
    month: '2-digit',
  }).format(d);
}

/** Ob ein Datum heute oder in der Zukunft liegt. */
export function isFuture(date: string): boolean {
  const d = parseLocal(date);
  const today = parseLocal(todayLocal());
  if (!d || !today) return false;
  return d.getTime() > today.getTime();
}

/**
 * Reine, zustandslose Logik für Tagesfortschritt und Dashboard.
 * Diese Funktionen hängen nicht von IndexedDB ab und sind daher
 * sehr einfach und schnell zu testen.
 */
import type { Activity, DayProgress, StoredState } from './types';

/** Liefert den erledigten Fortschritt einer Aktivität an einem Tag. */
export function getDoneCount(
  activity: Activity,
  progress: DayProgress,
): number {
  return Math.max(0, Math.trunc(progress[activity.id] ?? 0));
}

/** Ist eine Aktivität an diesem Tag als erledigt markiert? */
export function isDone(activity: Activity, progress: DayProgress): boolean {
  return getDoneCount(activity, progress) > 0;
}

/**
 * Wechselt den Status einer Aktivität an einem Tag.
 * Ohne Tagesziel: Klick toggelt zwischen 0 und 1.
 * Mit Tagesziel (>1): inkrementiert die Zählung pro Klick.
 */
export function toggleDayDone(
  activity: Activity,
  progress: DayProgress,
): DayProgress {
  const next = { ...progress };
  const current = getDoneCount(activity, progress);
  if (activity.dailyGoal > 1) {
    next[activity.id] = current + 1;
  } else {
    next[activity.id] = current > 0 ? 0 : 1;
  }
  return next;
}

/** Setzt eine konkrete Zählung (wird z. B. beim Laden/Sichern verwendet). */
export function setDayCount(
  activityId: string,
  count: number,
  progress: DayProgress,
): DayProgress {
  const next = { ...progress };
  if (count <= 0) {
    delete next[activityId];
  } else {
    next[activityId] = Math.max(0, Math.trunc(count));
  }
  return next;
}

/** Reduziert die Zählung um eins (Rückgängig). */
export function decrementDayCount(
  activityId: string,
  progress: DayProgress,
): DayProgress {
  return setDayCount(activityId, getDoneCountById(activityId, progress) - 1, progress);
}

export function getDoneCountById(
  activityId: string,
  progress: DayProgress,
): number {
  return Math.max(0, Math.trunc(progress[activityId] ?? 0));
}

/**
 * Dashboard-Zusammenfassung für einen Tag:
 * - erledigt/offen basierend auf dem Tagesziel (eine Aktivität ist
 *   "erledigt", wenn ihr Fortschritt ihr Ziel erreicht hat).
 */
export interface DaySummary {
  total: number;
  done: number;
  open: number;
  percent: number;
}

export function getDaySummary(
  activities: Activity[],
  progress: DayProgress,
): DaySummary {
  let done = 0;
  for (const a of activities) {
    const count = getDoneCount(a, progress);
    const target = a.dailyGoal > 0 ? a.dailyGoal : 1;
    if (count >= target) done += 1;
  }
  const total = activities.length;
  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
  return {
    total,
    done,
    open: total - done,
    percent,
  };
}

/** Kategorie-Zusammenfassung: je Kategorie erledigte / offene Aktivitäten. */
export interface CategoryStat {
  category: string;
  total: number;
  done: number;
}

export function getCategoryBreakdown(
  activities: Activity[],
  progress: DayProgress,
): CategoryStat[] {
  const map = new Map<string, CategoryStat>();
  for (const a of activities) {
    const key = a.category.trim() || 'Ohne Kategorie';
    let stat = map.get(key);
    if (!stat) {
      stat = { category: key, total: 0, done: 0 };
      map.set(key, stat);
    }
    const target = a.dailyGoal > 0 ? a.dailyGoal : 1;
    const done = getDoneCount(a, progress) >= target;
    stat.total += 1;
    if (done) stat.done += 1;
  }
  return Array.from(map.values()).sort((x, y) =>
    x.category.localeCompare(y.category),
  );
}

/**
 * Sanitiert einen beliebigen, potenziell beschädigten Zustand in einen
 * gültigen `StoredState`. Wirft nie. Entfernt ungültige Aktivitäten und Tage.
 */
export function sanitizeState(raw: unknown): StoredState {
  if (!raw || typeof raw !== 'object') {
    return emptyStateSafe();
  }
  const obj = raw as Partial<StoredState> & Record<string, unknown>;

  const activities = Array.isArray(obj.activities)
    ? obj.activities.map(sanitizeActivity).filter((a): a is Activity => a !== null)
    : [];

  const days: StoredState['days'] = {};
  if (obj.days && typeof obj.days === 'object') {
    for (const [date, progress] of Object.entries(obj.days as Record<string, unknown>)) {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;
      const cleaned = sanitizeProgress(progress);
      if (Object.keys(cleaned).length > 0) days[date] = cleaned;
    }
  }

  return {
    schemaVersion: 1,
    activities,
    days,
    updatedAt: typeof obj.updatedAt === 'string' ? obj.updatedAt : new Date().toISOString(),
  };
}

function emptyStateSafe(): StoredState {
  return {
    schemaVersion: 1,
    activities: [],
    days: {},
    updatedAt: new Date().toISOString(),
  };
}

function sanitizeActivity(v: unknown): Activity | null {
  if (!v || typeof v !== 'object') return null;
  const a = v as Record<string, unknown>;
  if (typeof a.name !== 'string' || a.name.trim() === '') return null;
  const goal = typeof a.dailyGoal === 'number' && a.dailyGoal > 0 ? a.dailyGoal : 0;
  return {
    id: typeof a.id === 'string' && a.id ? a.id : crypto.randomUUID(),
    name: a.name.trim(),
    description: typeof a.description === 'string' ? a.description : '',
    category: typeof a.category === 'string' ? a.category : 'Ohne Kategorie',
    dailyGoal: goal,
    createdAt: typeof a.createdAt === 'string' ? a.createdAt : new Date().toISOString(),
  };
}

function sanitizeProgress(v: unknown): DayProgress {
  const out: DayProgress = {};
  if (!v || typeof v !== 'object') return out;
  for (const [id, count] of Object.entries(v as Record<string, unknown>)) {
    if (typeof count !== 'number' || !Number.isFinite(count) || count <= 0) continue;
    out[id] = Math.trunc(count);
  }
  return out;
}

/**
 * Versionierter Persistenzlayer basierend auf IndexedDB.
 *
 * Designziele:
 * - Daten werden als einzelnes, versioniertes JSON-Objekt gespeichert.
 *   Das macht Migrationen und Validierung einfach und vorhersehbar.
 * - Lesevorgänge werfen NIE. Bei jedem Fehler (DB gesperrt, Parser-Fehler,
 *   veraltetes/zugewürdetes Format) wird ein sicherer leerer Zustand zurückgegeben.
 * - Migrationsfunktion ist versioniert und erweiterbar.
 */
import type { Activity, DayProgress, StoredState } from './types';
import { SCHEMA_VERSION, emptyState } from './types';
import { sanitizeState } from './dayLogic';

const DB_NAME = 'pulseboard';
const DB_VERSION = 1;
const STORE = 'state';
const KEY = 'main';

/** Einmalige, lazy initialisierte Verbindungsreferenz. */
let cachedDB: IDBDatabase | null = null;
let initPromise: Promise<IDBDatabase> | null = null;

/** Öffnet (und ggf. migriert) die Datenbank. Kapselt alle Fehler. */
export function initStore(): Promise<IDBDatabase> {
  if (cachedDB) return Promise.resolve(cachedDB);
  if (initPromise) return initPromise;

  initPromise = new Promise<IDBDatabase>((resolve, reject) => {
    try {
      const req = indexedDB.open(DB_NAME, DB_VERSION);

      req.onupgradeneeded = () => {
        const db = req.result;
        // Erster Start oder Versionsprung: neue Stores anlegen, falls fehlend.
        if (!db.objectStoreNames.contains(STORE)) {
          db.createObjectStore(STORE, { keyPath: 'key' });
        }
      };

      req.onsuccess = () => {
        cachedDB = req.result;
        resolve(cachedDB);
      };

      req.onerror = () => {
        reject(new Error(`IndexedDB konnte nicht geöffnet werden: ${req.error?.message}`));
      };
    } catch (err) {
      reject(err instanceof Error ? err : new Error(String(err)));
    }
  });

  return initPromise;
}

/** Liest den vollständigen, validierten und migrierten Zustand. Werf nie. */
export async function readState(): Promise<StoredState> {
  let db: IDBDatabase;
  try {
    db = await initStore();
  } catch {
    // Persistenz nicht verfügbar (z. B. Modus ohne Speicher). Start leer.
    return emptyState();
  }

  return new Promise<StoredState>((resolve) => {
    try {
      const tx = db.transaction(STORE, 'readonly');
      const store = tx.getStore();
      const req = store.get(KEY);

      req.onsuccess = () => {
        const raw = req.result ? req.result.value : undefined;
        resolve(migrateState(sanitizeState(raw)));
      };
      req.onerror = () => resolve(emptyState());
      tx.onerror = () => resolve(emptyState());
    } catch {
      resolve(emptyState());
    }
  });
}

/** Schreibt einen Zustand zurück. Werf nie – Fehler werden stillgeschleift. */
export async function writeState(state: StoredState): Promise<void> {
  let db: IDBDatabase;
  try {
    db = await initStore();
  } catch {
    return;
  }

  const payload = { key: KEY, value: state };
  try {
    const tx = db.transaction(STORE, 'readwrite');
    const store = tx.getStore();
    store.put(payload);
    tx.oncomplete = () => {};
    tx.onerror = () => {};
  } catch {
    // Absichtlich swallowed: Persistenzfehler dürfen die App nicht crashen.
  }
}

/**
 * Wendet registrierte Migrationen an, falls die gespeicherte Version
 * kleiner als die aktuelle ist. Jede Migration ist isoliert try/catch-ed.
 */
function migrateState(state: StoredState): StoredState {
  if (typeof state.schemaVersion !== 'number' || state.schemaVersion < SCHEMA_VERSION) {
    let migrated = state;
    for (let v = state.schemaVersion; v < SCHEMA_VERSION; v += 1) {
      const fn = MIGRATIONS[v];
      if (!fn) break;
      try {
        migrated = fn(migrated);
      } catch {
        // Bei einer fehlgeschlagenen Migration wird mit dem bisherigen
        // (bereits sanitisierten) Zustand fortgefahren.
        break;
      }
    }
    migrated = { ...migrated, schemaVersion: SCHEMA_VERSION };
    return migrated;
  }
  return state;
}

/**
 * Migrationsliste, indiziert mit der URSPRUNG-Version.
 * Für v1 gibt es keine vorherige Version; hier nur das Muster für künftige
 * Versionen (z. B. v1 -> v2).
 */
const MIGRATIONS: Record<number, (s: StoredState) => StoredState> = {
  // 1: (Platzhalter für v1 -> v2)
};

// ---------------------------------------------------------------------------
// Bequeme CRUD-Helfer. Alle lesen den aktuellen Zustand, wenden die Änderung
// an und schreiben zurück.
// ---------------------------------------------------------------------------

export async function listActivities(): Promise<Activity[]> {
  const state = await readState();
  return state.activities;
}

export async function saveActivity(activity: Activity): Promise<Activity> {
  const state = await readState();
  const existingIndex = state.activities.findIndex((a) => a.id === activity.id);
  if (existingIndex >= 0) {
    const activities = [...state.activities];
    activities[existingIndex] = activity;
    state.activities = activities;
  } else {
    state.activities = [...state.activities, activity];
  }
  state.updatedAt = new Date().toISOString();
  await writeState(state);
  return activity;
}

export async function removeActivity(activityId: string): Promise<void> {
  const state = await readState();
  state.activities = state.activities.filter((a) => a.id !== activityId);
  // Verwaite Fortschrittseinträge entfernen (Platte schonen).
  for (const date of Object.keys(state.days)) {
    if (state.days[date][activityId] !== undefined) {
      const next = { ...state.days[date] };
      delete next[activityId];
      state.days[date] = next;
    }
  }
  state.updatedAt = new Date().toISOString();
  await writeState(state);
}

export async function getDayProgress(date: string): Promise<DayProgress> {
  const state = await readState();
  return state.days[date] ?? {};
}

export async function setDayProgress(
  date: string,
  progress: DayProgress,
): Promise<void> {
  const state = await readState();
  const next = { ...state.days, [date]: progress };
  state.days = next;
  state.updatedAt = new Date().toISOString();
  await writeState(state);
}

/** Leitet alle gespeicherten Daten (JSON-Export). */
export async function exportData(): Promise<string> {
  const state = await readState();
  return JSON.stringify(state, null, 2);
}

/** Schreibt einen exportierten Zustand zurück (Import). Werf nie. */
export async function importData(json: string): Promise<StoredState> {
  const sanitized = sanitizeState(safeParse(json));
  await writeState(sanitized);
  return sanitized;
}

function safeParse(json: string): unknown {
  try {
    return JSON.parse(json);
  } catch {
    return null;
  }
}

/** Schließt die Verbindung (hauptsächlich für Tests/nützliches Cleanup). */
export function closeStore(): void {
  try {
    cachedDB?.close();
  } catch {
    // ignore
  }
  cachedDB = null;
  initPromise = null;
}

import { useCallback, useEffect, useState } from 'react';
import type { Activity, DayProgress, StoredState } from '@/lib/types';
import {
  getDayProgress,
  importData,
  listActivities,
  removeActivity,
  saveActivity,
  setDayProgress,
  writeState,
} from '@/lib/storage';
import {
  addDays,
  formatDayLabel,
  formatDayShort,
  isFuture,
  todayLocal,
} from '@/lib/dateUtils';
import {
  decrementDayCount,
  setDayCount,
  toggleDayDone,
} from '@/lib/dayLogic';

/**
 * Zentrale State-Verwaltung. Hält Aktivitäten, den Fortschritt je Tag und den
 * ausgewählten Tag. Lädt beim ersten Start aus der Persistenz und schreibt
 * nach jeder strukturellen Änderung zurück.
 */
export interface DayStore {
  activities: Activity[];
  selectedDate: string;
  selectedLabel: string;
  selectedIsFuture: boolean;
  progress: DayProgress;
  loading: boolean;
  error: string | null;

  reload: () => Promise<void>;
  addActivity: (a: Omit<Activity, 'id' | 'createdAt'>) => Promise<void>;
  updateActivity: (a: Activity) => Promise<void>;
  deleteActivity: (id: string) => Promise<void>;
  toggleDone: (activity: Activity) => Promise<void>;
  changeCount: (activity: Activity, delta: number) => Promise<void>;
  goTo: (delta: number) => Promise<void>;
  goToToday: () => Promise<void>;
  setDate: (date: string) => void;
  importFromJson: (json: string) => Promise<void>;
}

export function useDayStore(): DayStore {
  const [activities, setActivities] = useState<Activity[]>([]);
  const [days, setDays] = useState<Record<string, DayProgress>>({});
  const [selectedDate, setSelectedDate] = useState<string>(todayLocal());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const reload = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const state: StoredState = await loadFreshState();
      setActivities(state.activities);
      setDays(state.days);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Daten konnten nicht geladen werden.');
    } finally {
      setLoading(false);
    }
  }, []);

  // Einmaliges Laden beim ersten Render.
  useEffect(() => {
    void reload();
  }, [reload]);

  const persistActivities = useCallback(async (next: Activity[]) => {
    const state = await loadFreshState();
    state.activities = next;
    state.updatedAt = new Date().toISOString();
    await writeState(state);
  }, []);

  const persistDays = useCallback(async (next: Record<string, DayProgress>) => {
    const state = await loadFreshState();
    state.days = next;
    state.updatedAt = new Date().toISOString();
    await writeState(state);
  }, []);

  const addActivity = useCallback(
    async (input: Omit<Activity, 'id' | 'createdAt'>) => {
      const state = await loadFreshState();
      const activity: Activity = {
        ...input,
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
      };
      const next = [...state.activities, activity];
      setActivities(next);
      await persistActivities(next);
    },
    [persistActivities],
  );

  const updateActivity = useCallback(
    async (activity: Activity) => {
      const state = await loadFreshState();
      const next = state.activities.map((a) =>
        a.id === activity.id ? activity : a,
      );
      setActivities(next);
      await persistActivities(next);
    },
    [persistActivities],
  );

  const deleteActivity = useCallback(
    async (id: string) => {
      await removeActivity(id);
      const state = await loadFreshState();
      setActivities(state.activities);
    },
    [],
  );

  const toggleDone = useCallback(
    async (activity: Activity) => {
      if (isFuture(selectedDate)) return; // Zukunft darf nicht abgehakt werden
      const current = days[selectedDate] ?? {};
      const nextProgress = toggleDayDone(activity, current);
      const nextDays = { ...days, [selectedDate]: nextProgress };
      setDays(nextDays);
      await persistDays(nextDays);
    },
    [days, selectedDate, persistDays],
  );

  const changeCount = useCallback(
    async (activity: Activity, delta: number) => {
      if (isFuture(selectedDate)) return;
      const current = days[selectedDate] ?? {};
      const nextCount =
        delta > 0
          ? setDayCount(activity.id, getDoneCount(activity, current) + delta, current)
          : decrementDayCount(activity.id, current);
      const nextDays = { ...days, [selectedDate]: nextCount };
      setDays(nextDays);
      await persistDays(nextDays);
    },
    [days, selectedDate, persistDays],
  );

  const goTo = useCallback(
    async (delta: number) => {
      setSelectedDate((d) => addDays(d, delta));
    },
    [],
  );

  const goToToday = useCallback(() => {
    setSelectedDate(todayLocal());
  }, []);

  const setDate = useCallback((date: string) => {
    setSelectedDate(date);
  }, []);

  const importFromJson = useCallback(
    async (json: string) => {
      const state = await importData(json);
      setActivities(state.activities);
      setDays(state.days);
      await state;
    },
    [],
  );

  return {
    activities,
    selectedDate,
    selectedLabel: formatDayLabel(selectedDate),
    selectedIsFuture: isFuture(selectedDate),
    progress: days[selectedDate] ?? {},
    loading,
    error,
    reload,
    addActivity,
    updateActivity,
    deleteActivity,
    toggleDone,
    changeCount,
    goTo,
    goToToday,
    setDate,
    importFromJson,
  };
}

// Lokale Kopie, um einen zirkulären Import (dayLogic -> storage) zu vermeiden.
function getDoneCount(activity: Activity, progress: DayProgress): number {
  return Math.max(0, Math.trunc(progress[activity.id] ?? 0));
}

/**
 * Lädt immer den frischen Zustand aus der Persistenz. So bleibt der Speicher
 * die autoritative Quelle und In-Memory- und Disk-Werte bleiben konsistent.
 */
async function loadFreshState(): Promise<StoredState> {
  const [activities, days] = await Promise.all([
    listActivities(),
    readDaysAll(),
  ]);
  return {
    schemaVersion: 1,
    activities,
    days,
    updatedAt: new Date().toISOString(),
  };
}

async function readDaysAll(): Promise<Record<string, DayProgress>> {
  const state = await readStateAll();
  return state.days;
}

// Einfacher Wrapper, der die gesamte Tagekarte lädt.
async function readStateAll(): Promise<StoredState> {
  // readState ist in storage.ts implementiert; hier über listActivities +
  // einen direkten Gesamtladeaufruf, um Abhängigkeiten klein zu halten.
  const snapshot = await import('@/lib/storage');
  return snapshot.readState();
}

