32:   const dt = new Date(y, m - 1, d);
33:   // Verhindert stille Roll-over (z. B. 2021-02-31 -> März).
34:   if (
35:     dt.getFullYear() !== y ||
36:     dt.getMonth() !== m - 1 ||
37:     dt.getDate() !== d
38:   ) {
39:     return null;
40:   }
41:   return dt;
42: }
