import { useTheme } from '@/hooks/useTheme';

/** Schaltet zwischen hellem und dunklem Modum (Kopfzeilen-Symbol). */
export function ThemeToggle() {
  const { theme, toggle } = useTheme();
  const isDark = theme === 'dark';

  return (
    <button
      type="button"
      className="icon-btn"
      aria-label={
        isDark ? 'Hellen Modus aktivieren' : 'Dunklen Modus aktivieren'
      }
      aria-pressed={isDark}
      onClick={toggle}
    >
      {isDark ? (
        <svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M21 12.79A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8Z" />
        </svg>
      ) : (
        <svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M12 1v2M12 21v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M1 12h2M21 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41" stroke="currentColor" strokeWidth="2" strokeLinecap="round" fill="none" />
          <circle cx="12" cy="12" r="5" fill="currentColor" />
        </svg>
      )}
    </button>
  );
}

import type { CategoryStat, DaySummary } from '@/lib/dayLogic';

interface Props {
  summary: DaySummary;
  categories: CategoryStat[];
}

/** Fortschritts-Dashboard: vier Statistiken, Balken und Kategorie-Chips. */
export function Dashboard({ summary, categories }: Props) {
  return (
    <section className="card">
      <div className="dashboard">
        <div className="stat">
          <div className="value">{summary.done}</div>
          <div className="label">Erledigt</div>
        </div>
        <div className="stat">
          <div className="value">{summary.open}</div>
          <div className="label">Offen</div>
        </div>
        <div className="stat">
          <div className="value">{summary.total}</div>
          <div className="label">Gesamt</div>
        </div>
        <div className="stat">
          <div className="value">{summary.percent}%</div>
          <div className="label">Fortschritt</div>
        </div>

        <div
          className="progress-track"
          role="progressbar"
          aria-valuenow={summary.percent}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-label="Tagesfortschritt"
        >
          <div
            className="progress-fill"
            style={{ width: `${summary.percent}%` }}
          />
        </div>

        {categories.length > 0 && (
          <div className="categories">
            {categories.map((c) => (
              <span className="chip" key={c.category}>
                <strong>
                  {c.done}/{c.total}
                </strong>{' '}
                {c.category}
              </span>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

interface Props {
  label: string;
  isFuture: boolean;
  onPrev: () => void;
  onNext: () => void;
  onToday: () => void;
}

/** Tagesnavigation: Tag für Tag vor/zurück, Sprung zu „Heute". */
export function DayNavigation({
  label,
  isFuture,
  onPrev,
  onNext,
  onToday,
}: Props) {
  return (
    <section className="card">
      <div className="daynav">
        <button type="button" aria-label="Voriger Tag" onClick={onPrev}>
          ‹
        </button>
        <div className="day-title">
          {label}
          <span className="sub">
            {isFuture ? 'Zukunft' : 'Dein Tag'}
          </span>
        </div>
        <button type="button" aria-label="Nächster Tag" onClick={onNext}>
          ›
        </button>
        <button type="button" className="btn btn-ghost today-btn" onClick={onToday}>
          Heute
        </button>
      </div>
      {isFuture && (
        <div className="is-future-badge">
          Dieser Tag liegt in der Zukunft und kann noch nicht abgehakt werden.
        </div>
      )}
    </section>
  );
}

import type { ReactNode } from 'react';

interface Props {
  title: string;
  message: string;
  action?: ReactNode;
}

/** Leerer Zustand (z. B. keine Aktivitäten) mit optionalem Aktions-Button. */
export function EmptyState({ title, message, action }: Props) {
  return (
    <section className="card">
      <div className="empty">
        <svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M9 5H7a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-2M9 5a2 2 0 0 2 2 2h2a2 2 0 0 2-2-2M9 5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2m-6 9 2 2 4-4" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" fill="none" />
        </svg>
        <p style={{ margin: '0 0 4px', fontSize: '1rem', fontWeight: 600, color: 'var(--text)' }}>
          {title}
        </p>
        <p>{message}</p>
        {action && <div style={{ marginTop: 14 }}>{action}</div>}
      </div>
    </section>
  );
}

interface Props {
  message: string;
  onRetry: () => void;
}

/** Zeigt einen nicht-kritischen Fehler mit Wiederholungs-Button an. */
export function ErrorBanner({ message, onRetry }: Props) {
  return (
    <div className="error-banner" role="alert">
      <svg viewBox="0 0 24 24" aria-hidden="true" style={{ width: 20, height: 20, fill: 'currentColor', flex: '0 0 auto' }}>
        <path d="M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm1 15a1 1 0 1 1-2 0 1 1 0 0 1 2 0Zm-1-13a1 1 0 0 0-1 1v7a1 1 0 0 0 2 0V5a1 1 0 0 0-1-1Z" fill="currentColor" />
      </svg>
      <span>{message}</span>
      <button type="button" className="btn btn-ghost" onClick={onRetry}>
        Erneut versuchen
      </button>
    </div>
  );
}

/** Kleiner Ladezustand, während die Persistenz beim ersten Start gelesen wird. */
export function LoadingState() {
  return <div className="loading">Laden…</div>;
}

