46:   const d = parseLocal(date);
47:   if (!d) return date;
48:   return new Intl.DateTimeFormat('de-DE', {
49:     weekday: 'long',
50:     day: '2-digit',
51:     month: 'short',
52:     year: 'numeric',
53:   }).format(d);
54: }
